class _ReviewPageState extends State<ReviewPage> { final controller = TextEditingController(); bool? correct; int seed = 0; late final Concept concept = Concept(id:'demo',documentId:'democracy',subjectId:'social',unitId:'democracy',name:'Representative democracy',statement:'Citizens elect representatives.',explanation:'Representatives make political decisions on citizens’ behalf.',confidence:.97,sourceEvidence:const [SourceEvidence(documentId:'democracy',pageNumber:1,sourceType:SourceType.printedText,text:'Representative democracy uses elected representatives.',confidence:.96)],createdAt:DateTime.utc(2025),updatedAt:DateTime.utc(2025)); @override Widget build(BuildContext context) { final q = GeneratedQuestion(id:'q$seed',conceptId:concept.id,prompt:'What happens in a representative democracy?',expectedAnswer:concept.statement,explanation:concept.explanation,type:QuestionType.shortAnswer,variantKey:'recall-$seed',generationSeed:seed); return ListView(padding: const EdgeInsets.all(24), children: [Text('Social Studies · Democracy', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 24), Text('Question', style: Theme.of(context).textTheme.labelLarge), Text(q.prompt, style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 20), TextField(controller: controller, onSubmitted: (_) => _submit(q), decoration: const InputDecoration(border: OutlineInputBorder(), labelText: 'Your answer')), const SizedBox(height: 12), FilledButton(onPressed: () => _submit(q), child: const Text('Submit')), if(correct != null) Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(correct! ? 'Correct' : 'Keep reviewing', style: Theme.of(context).textTheme.titleLarge), Text('Correct answer: ${q.expectedAnswer}'), Text(q.explanation), const Divider(), const Text('Source: Democracy Handout · Page 1'), Wrap(spacing: 8, children: [TextButton(onPressed: _source, child: const Text('View source')), TextButton(onPressed: _report, child: const Text('Report bad question')), FilledButton(onPressed: () => setState(() { seed++; correct=null; controller.clear(); }), child: const Text('Next'))])])))]); } void _submit(GeneratedQuestion q) => setState(() => correct = gradeAnswer(controller.text, q.expectedAnswer)); void _source() => showDialog(context: context, builder: (_) => const AlertDialog(title: Text('Democracy Handout · Page 1'), content: Text('Original page\n\nEvidence: “Representative democracy uses elected representatives.”\nType: printed text · confidence 96%'))); void _report() => showModalBottomSheet(context: context, builder: (_) => ListView(shrinkWrap:true, children: ['Wrong answer','Unsupported by source','Confusing wording','Duplicate','Other'].map((r) => ListTile(title: Text(r), onTap: () => Navigator.pop(context))).toList())); }
